#!/usr/bin/env python3
"""Build assets/icons.svg from the catalogue and the manifest.

    python3 tools/icons_sprite.py           # write the sprite
    python3 tools/icons_sprite.py --check   # exit 1 when the sprite is stale

The catalogue is `assets/icons/` — every glyph of Lucide 1.77.0, one file each, drawn on a 24-unit
grid with a 2-unit stroke (ISC licence, `assets/icons-ISC.txt`). The manifest names the glyphs the
product ships; this tool turns exactly those into one `<symbol>` per name, so a screen pays for what
it uses and a new glyph is one line in the manifest.

A hand-drawn glyph belongs in `assets/icons/` only when the catalogue lacks the concept; the icon
check (`tools/icons.py`) then proves it sits on the same grid.
"""
import json
import pathlib
import re
import sys

ROOT = pathlib.Path(__file__).resolve().parent.parent
CATALOGUE = ROOT / "assets" / "icons"
MANIFEST = ROOT / "assets" / "icons-manifest.json"
SPRITE = ROOT / "assets" / "icons.svg"

HEADER = """<svg xmlns="http://www.w3.org/2000/svg" width="0" height="0" aria-hidden="true">
  <!-- ARC icon sprite — generated by tools/icons_sprite.py. Do not edit.
       Source: assets/icons/ (Lucide 1.77.0, ISC — assets/icons-ISC.txt) · the manifest names what ships.
       Use it as: <use href="assets/icons.svg#check"> inside an element with class arc-icon.
       The catalogue page lists every glyph: icons.html, rendered to docs/icons.png. -->
"""
FOOTER = "</svg>\n"
ATTRIBUTE = re.compile(r'\s(stroke|fill|stroke-width|stroke-linecap|stroke-linejoin)="[^"]*"')


def symbol(name: str) -> str:
    source = (CATALOGUE / f"{name}.svg").read_text(encoding="utf-8")
    body = re.sub(r"^.*?<svg\b[^>]*>", "", source, flags=re.S)
    body = re.sub(r"</svg>\s*$", "", body, flags=re.S)
    body = re.sub(r"\s+", " ", body).strip()
    if not body.startswith("<"):
        raise SystemExit(f"{name}: the catalogue file carries no drawable element")
    # the <svg> element carries fill/stroke/linecap; the stylesheet owns those, so only geometry stays
    body = ATTRIBUTE.sub("", body)
    return f'  <symbol id="{name}" viewBox="0 0 24 24">{body}</symbol>\n'


def build() -> str:
    manifest = json.loads(MANIFEST.read_text(encoding="utf-8"))
    names = manifest["glyphs"]
    if not CATALOGUE.is_dir():
        # a consumer's pack ships the sprite and the manifest, not the catalogue: nothing to rebuild from,
        # so the check compares the sprite's names with the manifest and says what it could not do
        sprite = SPRITE.read_text(encoding="utf-8") if SPRITE.exists() else ""
        built = re.findall(r'<symbol id="([a-z0-9-]+)"', sprite)
        if set(built) != set(names):
            raise SystemExit("the sprite and the manifest differ: " + ", ".join(sorted(set(names) ^ set(built))))
        raise _Shipped(len(built))
    missing = [n for n in names if not (CATALOGUE / f"{n}.svg").exists()]
    if missing:
        raise SystemExit("not in the catalogue: " + ", ".join(missing))
    return HEADER + "".join(symbol(n) for n in names) + FOOTER


class _Shipped(Exception):
    """The pack has no catalogue: the sprite is the shipped artefact, so there is nothing to rebuild."""


def main(argv: list[str]) -> int:
    try:
        text = build()
    except _Shipped as shipped:
        print(f"assets/icons.svg is the shipped sprite — {shipped.args[0]} glyphs match the manifest (no catalogue in this pack)")
        return 0
    if "--check" in argv:
        current = SPRITE.read_text(encoding="utf-8") if SPRITE.exists() else ""
        if current != text:
            print("assets/icons.svg is stale — run: python3 tools/icons_sprite.py")
            return 1
        print("assets/icons.svg is current")
        return 0
    SPRITE.write_text(text, encoding="utf-8")
    count = text.count("<symbol")
    print(f"assets/icons.svg written — {count} glyphs, {len(text)} bytes")
    return 0


if __name__ == "__main__":
    sys.exit(main(sys.argv[1:]))
